query=query($owner: String!, $name: String!, $cursor: String) {
  repository(owner: $owner, name: $name) {
    milestones(states: OPEN, first: 100, after: $cursor, orderBy: {field: NUMBER, direction: ASC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        number
        title
        issues(states: OPEN) { totalCount }
        closedIssues: issues(states: CLOSED) { totalCount }
      }
    }
  }
}

query=query($owner: String!, $name: String!, $cursor: String, $milestone: String) {
  repository(owner: $owner, name: $name) {
    issues(states: OPEN, first: 100, after: $cursor, filterBy: {milestoneNumber: $milestone}, orderBy: {field: CREATED_AT, direction: ASC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        number
        title
        milestone { number title }
        labels(first: 100) { nodes { name } }
        blockedBy(first: 100) { nodes { number state } }
        blocking(first: 100) { nodes { number state } }
        closedByPullRequestsReferences(first: 100, includeClosedPrs: true) { nodes { number state } }
      }
    }
  }
}

